\begin{tikzpicture}[x=1.35cm,y=0.78cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{originalBlue}{HTML}{268CFF}
\definecolor{reflectionRed}{HTML}{EF6068}
\definecolor{dilationPurple}{HTML}{8B5CC7}
\draw[->,black,line width=0.5pt] (-1.7,0)--(1.85,0) node[right] {$x$};
\draw[->,black,line width=0.5pt] (0,-3.4)--(0,3.6) node[above] {$y$};
\draw[originalBlue,line width=0.8pt,domain=-1.48:1.48,samples=81] plot (\x,{\x*\x*\x});
\draw[reflectionRed,dashed,line width=0.8pt,domain=-1.48:1.48,samples=81] plot (\x,{-\x*\x*\x});
\draw[dilationPurple,densely dotted,line width=0.8pt,domain=-1.17:1.17,samples=81] plot (\x,{2*\x*\x*\x});
\fill[originalBlue] (1,1) circle (1.5pt) node[right,black] {$(1,1)$};
\node[anchor=west,originalBlue] at (1.48,3.24) {$y=f(x)$};
\node[anchor=east,reflectionRed] at (-1.48,3.24) {$y=f(-x)$};
\node[anchor=south west,dilationPurple] at (0.4,3.6) {$y=2f(x)$};
